namespace UniversalPOS.Domain.Entities;
public class PosTerminal { public int Id {get; private set;} public string Code {get; private set;}=string.Empty; public string Name {get; private set;}=string.Empty; public bool IsActive {get; private set;}=true; private PosTerminal(){} public PosTerminal(string code,string name){if(string.IsNullOrWhiteSpace(code)||string.IsNullOrWhiteSpace(name))throw new ArgumentException("Terminal code and name are required.");Code=code.Trim();Name=name.Trim();} public void Rename(string name){if(string.IsNullOrWhiteSpace(name))throw new ArgumentException("Name is required.");Name=name.Trim();} public void Deactivate()=>IsActive=false; public void Activate()=>IsActive=true; }
